func TestBaselineCoverageManifest(t *testing.T) {
	if got := len(baselineCoverageManifest); got != baselineCoverageManifestTotal {
		t.Fatalf("baseline manifest total: got %d want %d", got, baselineCoverageManifestTotal)
	}
	unique := map[string]bool{}
	perFile := map[string]int{}
	for _, entry := range baselineCoverageManifest {
		unique[fmt.Sprintf("%s\x00%s\x00%q", entry.File, entry.Helper, entry.Markers)] = true
		perFile[entry.File]++
	}
	if got := len(unique); got != baselineCoverageManifestUnique {
		t.Fatalf("baseline manifest unique count: got %d want %d", got, baselineCoverageManifestUnique)
	}
	for file, want := range baselineCoverageManifestPerFile {
		if got := perFile[file]; got != want {
			t.Fatalf("baseline manifest count for %s: got %d want %d", file, got, want)
		}
	}

	covered, err := baselineCoverageStringLiterals()
	if err != nil {
		t.Fatal(err)
	}
	var missing []string
	for _, entry := range baselineCoverageManifest {
		for _, marker := range entry.Markers {
			if marker != "" && !covered[marker] {
				missing = append(missing, fmt.Sprintf("%s %s marker %q", entry.File, entry.Helper, marker))
			}
		}
	}
	if len(missing) > 0 {
		limit := minInt(len(missing), 20)
		t.Fatalf("baseline coverage markers missing from Go source: %d\n%s", len(missing), strings.Join(missing[:limit], "\n"))
	}
}

func baselineCoverageStringLiterals() (map[string]bool, error) {
	files, err := filepath.Glob("*.go")
	if err != nil {
		return nil, err
	}
	covered := map[string]bool{}
	fset := token.NewFileSet()
	for _, name := range files {
		if name == "baseline_coverage_manifest_test.go" {
			continue
		}
		file, err := parser.ParseFile(fset, name, nil, 0)
		if err != nil {
			return nil, err
		}
		ast.Inspect(file, func(node ast.Node) bool {
			lit, ok := node.(*ast.BasicLit)
			if !ok || lit.Kind != token.STRING {
				return true
			}
			value, err := strconv.Unquote(lit.Value)
			if err == nil {
				covered[value] = true
			}
			return true
		})
	}
	return covered, nil
}
